// src/frontend/shared.ts
function el(tag, className = "", content = "") {
  const node = document.createElement(tag);
  if (className)
    node.className = className;
  if (content)
    node.textContent = content;
  return node;
}
function button(label, className = "lp-button") {
  const node = el("button", className, label);
  node.type = "button";
  return node;
}
function formatTime(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime()))
    return "";
  return new Intl.DateTimeFormat(undefined, { hour: "numeric", minute: "2-digit" }).format(date);
}
function formatDate(value, detail = false) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime()))
    return String(value || "");
  return new Intl.DateTimeFormat(undefined, detail ? { weekday: "short", month: "short", day: "numeric", hour: "numeric", minute: "2-digit" } : { month: "short", day: "numeric" }).format(date);
}
function dateTimeLocal(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime()))
    return "";
  const offset = date.getTimezoneOffset() * 60000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 16);
}
function inputValue(input) {
  return input.value.trim();
}
function requestId(prefix = "req") {
  return `${prefix}_${globalThis.crypto?.randomUUID?.() || `${Date.now()}_${Math.random().toString(36).slice(2)}`}`;
}

// src/frontend/components/ui.ts
function classes(...values) {
  return values.filter(Boolean).join(" ");
}
function identityBlock(options) {
  const root = el("div", classes("lp-identity", options.prominent && "lp-identity-prominent", options.centered && "lp-identity-centered", options.className));
  const line = el("div", "lp-identity-line");
  line.appendChild(el("strong", "lp-identity-name", options.name));
  if (options.meta)
    line.appendChild(el("span", "lp-identity-meta", options.meta));
  root.appendChild(line);
  if (options.description)
    root.appendChild(el("p", "lp-identity-description", options.description));
  return root;
}
function actionGroup(className = "") {
  return el("div", classes("lp-actions", className));
}
function sectionBlock(label, help = "", className = "") {
  const section = el("section", classes("lp-section", className));
  const head = el("header", "lp-section-head");
  head.appendChild(el("div", "lp-section-label", label));
  if (help)
    head.appendChild(el("p", "lp-section-help", help));
  const body = el("div", "lp-section-body");
  section.append(head, body);
  return { section, body };
}
function fieldBlock(label, control, help = "") {
  const field = el("label", "lp-field");
  field.appendChild(el("span", "lp-field-label", label));
  field.appendChild(control);
  if (help)
    field.appendChild(el("span", "lp-field-help", help));
  return field;
}
function controlRow(label, control, help = "") {
  const row = el("label", "lp-card lp-control-row");
  const copy = el("span", "lp-control-copy");
  copy.appendChild(el("span", "lp-control-label", label));
  if (help)
    copy.appendChild(el("span", "lp-control-help", help));
  row.append(copy, control);
  return row;
}
function disclosure(label, ...children) {
  const root = el("details", "lp-disclosure");
  root.append(el("summary", "", label), ...children);
  return root;
}
function showPocketSheet(anchor, title, content, options = {}) {
  const parent = anchor.closest(".lumiphone-shell") || anchor.closest('[role="dialog"]') || anchor.parentElement;
  if (!parent)
    return;
  const dialog = el("dialog", "lp-sheet");
  const panel = el("div", "lp-sheet-panel");
  const heading = el("h2", "lp-title", title);
  dialog.setAttribute("aria-label", title);
  const close = el("button", "lp-button lp-sheet-close", options.closeLabel || "Done");
  close.type = "button";
  const home = content.parentNode;
  const marker = document.createComment("sheet content");
  home?.insertBefore(marker, content);
  const dismiss = () => {
    if (typeof dialog.close === "function")
      dialog.close();
    else {
      dialog.removeAttribute("open");
      dialog.dispatchEvent(new dialog.ownerDocument.defaultView.Event("close"));
    }
  };
  close.addEventListener("click", dismiss);
  dialog.addEventListener("keydown", (event) => {
    if (event.key === "Escape" || event.key === "Tab")
      event.stopPropagation();
    if (event.key === "Escape") {
      event.preventDefault();
      dismiss();
    }
  });
  dialog.addEventListener("click", (event) => {
    if (event.target === dialog)
      dismiss();
  });
  dialog.addEventListener("close", () => {
    const active = dialog.ownerDocument.activeElement;
    const restoreFocus = !active || active === dialog.ownerDocument.body || dialog.contains(active);
    if (home)
      marker.replaceWith(content);
    dialog.remove();
    options.onDismiss?.();
    if (restoreFocus && anchor.isConnected)
      anchor.focus({ preventScroll: true });
  }, { once: true });
  panel.append(heading, content, close);
  dialog.append(panel);
  parent.append(dialog);
  const bounds = parent.getBoundingClientRect();
  const viewport = parent.ownerDocument.defaultView;
  if (parent.matches(".lumiphone-shell") && viewport) {
    const layoutWidth = parent.offsetWidth;
    const zoom = layoutWidth && bounds.width ? bounds.width / layoutWidth : 1;
    const layoutPx = (pixels) => pixels / zoom;
    dialog.style.position = "fixed";
    dialog.style.margin = "0";
    dialog.style.left = `${layoutPx(bounds.left + 12)}px`;
    dialog.style.top = "auto";
    dialog.style.bottom = `${layoutPx(Math.max(12, viewport.innerHeight - bounds.bottom + 24))}px`;
    dialog.style.width = `${layoutPx(Math.max(0, bounds.width - 24))}px`;
    dialog.style.maxHeight = `${layoutPx(Math.max(120, bounds.height - 70))}px`;
  } else if (viewport) {
    const layoutWidth = parent.offsetWidth;
    const zoom = layoutWidth && bounds.width ? bounds.width / layoutWidth : 1;
    Object.assign(dialog.style, { position: "fixed", margin: "0", left: `${viewport.innerWidth / 2 / zoom}px`, top: `${viewport.innerHeight / 2 / zoom}px`, bottom: "auto", transform: "translate(-50%,-50%)", width: `${Math.min(440, Math.max(0, viewport.innerWidth / zoom - 32))}px`, maxHeight: `calc(${viewport.innerHeight / zoom}px - 48px - var(--app-interactive-safe-top,0px))` });
  }
  if (typeof dialog.showModal === "function")
    dialog.showModal();
  else
    dialog.setAttribute("open", "");
  return { dismiss };
}
function outgoingSurface(accent) {
  const hex = /^#([0-9a-f]{6})$/i.exec(accent)?.[1] || "8b7dff";
  let rgb = [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
  const luminance = () => rgb.map((v) => v / 255).map((v) => v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4).reduce((sum, v, i) => sum + v * [0.2126, 0.7152, 0.0722][i], 0);
  while (luminance() > 0.16)
    rgb = rgb.map((v) => Math.floor(v * 0.95));
  return "#" + rgb.map((v) => v.toString(16).padStart(2, "0")).join("");
}
function avatarColor(identity) {
  const hash = Array.from(identity).reduce((n, c) => n * 31 + c.charCodeAt(0) >>> 0, 0);
  return `hsl(${hash % 360} 27% 34%)`;
}

// src/frontend/components/lumistry-user-photo.ts
function personaPhotoSheet(options) {
  const box = el("div", "lp-stack");
  box.append(el("p", "lp-copy", "Send a described photo, or choose an image. Your match reads the visible description you write."));
  const description = el("textarea", "lp-textarea");
  description.rows = 4;
  description.maxLength = 1500;
  description.placeholder = "What does the photo show?";
  description.setAttribute("aria-label", "Photo description");
  const comment = el("textarea", "lp-textarea");
  comment.rows = 2;
  comment.maxLength = 12000;
  comment.placeholder = "Optional message";
  comment.setAttribute("aria-label", "Photo message");
  const includesSelf = el("input");
  includesSelf.type = "checkbox";
  includesSelf.checked = true;
  const selfLabel = el("label", "lp-row");
  selfLabel.append(includesSelf, el("span", "", "This photo shows me"));
  const aspect = el("select", "lp-select");
  aspect.setAttribute("aria-label", "Photo aspect");
  for (const value of ["portrait", "landscape", "square"]) {
    const o = el("option", "", value);
    o.value = value;
    aspect.append(o);
  }
  const preview = el("div", "lp-stack"), status = el("p", "lp-copy");
  status.setAttribute("role", "status");
  let imageId, imageUrl, pending = false;
  const use = (choice) => {
    imageId = choice.imageId;
    imageUrl = choice.url;
    description.value = choice.description || "";
    aspect.value = choice.aspect || "portrait";
    if (choice.comment !== undefined)
      comment.value = choice.comment;
    if (choice.includesSelf !== undefined)
      includesSelf.checked = choice.includesSelf;
    preview.replaceChildren();
    if (choice.url) {
      const image = el("img");
      image.src = choice.url;
      image.alt = "Selected photo";
      image.style.cssText = "max-width:100%;max-height:240px;object-fit:contain;border-radius:12px";
      preview.append(image);
    }
  };
  if (options.selected)
    use(options.selected);
  const choices = el("div", "lp-stack");
  const gallery = button("Choose from Gallery", "lp-button");
  gallery.disabled = options.galleryAvailable === false;
  gallery.addEventListener("click", () => {
    if (!pending)
      options.gallery({ description: description.value, aspect: aspect.value, comment: comment.value, includesSelf: includesSelf.checked, imageId, url: imageUrl });
  });
  choices.append(gallery);
  options.profile?.photoPlan.forEach((plan, index) => {
    if (!plan.description)
      return;
    const b = button(`My profile photo ${index + 1}`, "lp-button lp-button-quiet");
    b.addEventListener("click", () => {
      if (pending)
        return;
      const photo = options.profile?.photos.find((p) => p.planIndex === index);
      use({ description: plan.description, imageId: photo?.source.kind === "gallery" ? photo.source.imageId : undefined, url: photo?.url, aspect: plan.aspect });
      includesSelf.checked = plan.subjectIds.includes("self");
    });
    choices.append(b);
  });
  const clear = button("Description only", "lp-button lp-button-quiet");
  clear.addEventListener("click", () => {
    if (!pending) {
      imageId = undefined;
      imageUrl = undefined;
      preview.replaceChildren();
    }
  });
  choices.append(clear);
  const send = button("Send photo", "lp-button lp-button-primary");
  send.type = "button";
  send.addEventListener("click", () => {
    if (pending)
      return;
    const text = description.value.trim();
    if (!text) {
      status.textContent = "Describe what is visible in the photo.";
      description.focus();
      return;
    }
    pending = true;
    send.disabled = true;
    description.disabled = comment.disabled = includesSelf.disabled = aspect.disabled = true;
    status.textContent = "Sending…";
    const finish = (error) => {
      if (error) {
        pending = false;
        send.disabled = false;
        description.disabled = comment.disabled = includesSelf.disabled = aspect.disabled = false;
        status.textContent = error;
      } else
        options.dismiss();
    };
    try {
      options.send({ description: text, includesSelf: includesSelf.checked, aspect: aspect.value, ...imageId ? { imageId } : {} }, comment.value.trim(), finish);
    } catch (error) {
      finish(error instanceof Error ? error.message : "Unable to send photo.");
    }
  });
  box.append(choices, preview, fieldBlock("Visible photo description", description), selfLabel, fieldBlock("Framing", aspect), fieldBlock("Message (optional)", comment), status, send);
  return box;
}

