var ADULT_PREFERENCE_STATES = [["unknown", "Unknown"], ["opt_in", "Interested"], ["opt_for_now", "Interested for now"], ["opt_out", "Not interested"], ["private_not_shared", "In-character secret · do not disclose"]];
var validKey = (s) => /^[a-z][a-z0-9_]{0,99}$/.test(s) && !["constructor", "prototype", "__proto__"].includes(s);
function normalizeAdultPreferences(raw) {
  if (raw === undefined)
    return;
  if (raw?.version !== 1 || !raw.terms || !raw.species || typeof raw.terms !== "object" || typeof raw.species !== "object" || Array.isArray(raw.terms) || Array.isArray(raw.species) || JSON.stringify(raw).length > 80000)
    return;
  const rows = (v, max) => {
    const entries = Object.entries(v);
    if (entries.length > max || entries.some(([id, state]) => !validKey(id) || !ADULT_PREFERENCE_STATES.some(([s]) => s === state)))
      return;
    return Object.fromEntries(entries);
  };
  const terms = rows(raw.terms, 500), species = rows(raw.species, 400);
  return terms && species ? { version: 1, terms, species } : undefined;
}
