    return { love: ui?.loveDraft || lovePreferences(d.relationships.preferences), experience: normalizeExperience(g.experience), content: ui?.contentEdited || d.experiencePreferences ? ui?.contentDraft || d.experiencePreferences : undefined, pipeline: ui?.pipelineDraft || d.pipeline };
