    return { populationWorld: ui?.populationWorldDraft || d.populationWorld, worldGuide: ui?.worldGuideDraft || d.worldGuide, worldContext: ui?.worldContextDraft ?? d.worldContext, worldFields: ui?.worldFieldsDraft ?? d.worldFields, appearanceDiversity: g.appearanceDiversity !== false, adultJobs: g.adultJobs !== false, allTropes: g.allTropes === true };
