// src/frontend/apps/lumistry-settings-state.ts
function acknowledgeSetupSettings(ui, d, groups, direct = false) {
  for (const group of groups) {
    if (ui.settingsBaselines)
      delete ui.settingsBaselines[group];
    if (group === "world") {
      ui.populationWorldDraft = undefined;
      ui.worldGuideDraft = undefined;
      ui.worldContextDraft = undefined;
      ui.worldFieldsDraft = undefined;
      ui.worldSettingsBaseline = undefined;
      if (ui.generationDraft)
        for (const k of ["adultJobs", "appearanceDiversity", "allTropes"])
          ui.generationDraft[k] = d.generationSettings[k];
    }
    if (group === "experience") {
      ui.loveDraft = undefined;
      ui.pipelineDraft = undefined;
      ui.contentDraft = undefined;
      ui.contentEdited = undefined;
      if (ui.generationDraft)
        ui.generationDraft.experience = structuredClone(d.generationSettings.experience);
    }
    if ((direct && group === "discovery" || !direct && group === "app") && ui.generationDraft)
      ui.generationDraft.creation = structuredClone(d.generationSettings.creation);
    if (group === "app") {
      if (!direct && ui.settingsBaselines)
        delete ui.settingsBaselines.discovery;
      ui.bankDraft = undefined;
      ui.appThemeDraft = undefined;
    }
  }
  ui.directBaseline = undefined;
}

