class PerformanceLedger {
  scopes = new Map;
  record(scope, stage, ms, units = 0) {
    if (!Number.isFinite(ms) || ms < 0)
      return;
    let entries = this.scopes.get(scope);
    if (!entries) {
      entries = new Map;
      this.scopes.set(scope, entries);
      if (this.scopes.size > 32)
        this.scopes.delete(this.scopes.keys().next().value);
    }
    const previous = entries.get(stage) || { count: 0, totalMs: 0, maxMs: 0, lastMs: 0, units: 0 };
    if (!entries.has(stage) && entries.size >= 64)
      entries.delete(entries.keys().next().value);
    entries.set(stage, { count: previous.count + 1, totalMs: previous.totalMs + ms, maxMs: Math.max(previous.maxMs, ms), lastMs: ms, units: previous.units + Math.max(0, units) });
  }
  snapshot(scope) {
    return Object.fromEntries([...this.scopes.get(scope) || []].map(([key, value]) => [key, { ...value }]));
  }
}
