function icon2(name) {
  const span = el("span", "na-icon");
  span.setAttribute("aria-hidden", "true");
  span.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name] || paths.more}"/></svg>`;
  return span;
}
function tool(label, name, run, className = "na-icon-button") {
  const b = button("", className);
  b.setAttribute("aria-label", label);
  b.title = label;
  b.append(icon2(name));
  b.onclick = run;
  return b;
}
function textButton(label, run, className = "na-button") {
  const b = button(label, className);
  b.onclick = run;
  return b;
}
function go(h, panel = "", selected) {
  h.ui.panels[h.app] = panel;
  if (selected !== undefined)
    h.ui.selected[h.app] = selected;
  h.render();
}
function header(title, back, ...actions) {
  const root = el("header", "na-header");
  root.append(back, el("h1", "", title), ...actions);
  return root;
}
function subBack(h, panel = "", label = "Back") {
  return tool(label, "back", () => go(h, panel));
}
function scroll(...nodes) {
  const root = el("div", "na-scroll");
  root.append(...nodes);
  return root;
}
function bottomNav(h, items, current) {
  const root = el("nav", "na-bottom-nav");
  root.setAttribute("aria-label", `${h.app} navigation`);
  for (const [id, label, name] of items) {
    const b = tool(label, name, () => go(h, id), "na-nav-item");
    b.append(el("span", "", label));
    if (id === current)
      b.setAttribute("aria-current", "page");
    root.append(b);
  }
  return root;
}
function empty2(title, copy, name = "bookmark") {
  const root = el("div", "na-empty");
  root.append(icon2(name), el("h3", "", title), el("p", "", copy));
  return root;
}
function avatar(name, className = "na-avatar") {
  return el("span", className, Array.from(name || "?")[0]);
}

// src/frontend/components/attachment-menu.ts
function attachmentMenu(anchor, items, dismissed = () => {}) {
  const host = anchor.closest(".lp-compose-stack") || anchor.parentElement, menu = el("div", "lp-attach-menu"), id = "attach-" + globalThis.crypto.randomUUID();
  menu.id = id;
  menu.setAttribute("role", "menu");
  menu.setAttribute("aria-label", "Attach to conversation");
  anchor.setAttribute("aria-expanded", "true");
  anchor.setAttribute("aria-controls", id);
  anchor.setAttribute("aria-haspopup", "menu");
  let closed = false;
  const close = (focus = false) => {
    if (closed)
      return;
    closed = true;
    menu.remove();
    anchor.setAttribute("aria-expanded", "false");
    anchor.removeAttribute("aria-controls");
    document.removeEventListener("pointerdown", outside, true);
    dismissed();
    if (focus && anchor.isConnected)
      anchor.focus({ preventScroll: true });
  };
  const outside = (event) => {
    if (!menu.contains(event.target) && !anchor.contains(event.target))
      close();
  };
  for (const item of items) {
    const b = textButton("", () => {
      close();
      item.run();
    }, "lp-attach-menu-item");
    b.setAttribute("role", "menuitem");
    b.append(icon2(item.icon), el("span", "", item.label));
    menu.append(b);
  }
  menu.onkeydown = (event) => {
    const buttons = [...menu.querySelectorAll("button")], index = buttons.indexOf(document.activeElement);
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      close(true);
    } else if (event.key === "Tab")
      close(true);
    else if (["ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) {
      event.preventDefault();
      buttons[event.key === "Home" ? 0 : event.key === "End" ? buttons.length - 1 : (index + (event.key === "ArrowUp" ? -1 : 1) + buttons.length) % buttons.length]?.focus();
    }
  };
  host.append(menu);
  document.addEventListener("pointerdown", outside, true);
  menu.querySelector("button")?.focus();
  return () => close();
}

