      b.setAttribute("aria-label", `${options.verb} ${options.verb === "Insert" ? "emote" : "sticker"} ${stickerLabel(sticker)}${sticker.packId ? " (" + packs.find((p) => p.id === sticker.packId)?.name + ")" : ""}`);
