// src/frontend/apps/native-ui.ts
var newNativeUI = () => ({ panels: {}, selected: {}, drafts: {}, private: false, quizAnswers: {} });
var act5 = (label, run, primary = false) => {
  const b = button(label, `lp-button${primary ? " lp-button-primary" : ""}`);
  b.onclick = run;
  return b;
};
var card = (title, copy = "") => {
  const root = el("section", "lp-native-card");
  root.append(el("h3", "", title));
  if (copy)
    root.append(el("p", "lp-copy", copy));
  return root;
};
function input2(h, key, label, type = "text", initial = "") {
  const control = el("input", "lp-input");
  control.type = type;
  if (type === "number")
    control.step = "any";
  control.name = key;
  control.value = h.ui.drafts[key] ?? initial;
  control.oninput = () => {
    h.ui.drafts[key] = control.value;
  };
  return fieldBlock(label, control);
}
function textarea(h, key, label) {
  const control = el("textarea", "lp-textarea");
  control.rows = 3;
  control.name = key;
  control.value = h.ui.drafts[key] || "";
  control.oninput = () => {
    h.ui.drafts[key] = control.value;
  };
  return fieldBlock(label, control);
}
function select4(h, key, label, options, initial = "") {
  const control = el("select", "lp-select");
  control.name = key;
  for (const [value, label] of options)
    control.append(new Option(label, value));
  control.value = h.ui.drafts[key] ?? (initial || options[0]?.[0] || "");
  control.onchange = () => {
    h.ui.drafts[key] = control.value;
  };
  return fieldBlock(label, control);
}
function form(h, title, fields, submitLabel, send) {
  const root = card(title), form = el("form", "lp-native-form"), submit = button(submitLabel, "lp-button lp-button-primary");
  submit.type = "submit";
  submit.disabled = h.busy;
  form.append(...fields, submit);
  form.onsubmit = (event) => {
    event.preventDefault();
    if (h.busy)
      return;
    send(Object.fromEntries(new FormData(form).entries()));
  };
  root.append(form);
  return root;
}
function conversations(h, key = "recipient") {
  return select4(h, key, "Send to", [["", "Choose a conversation"], ...h.state.conversations.filter((c) => !c.archived && conversationVisibleOnDevice(h.state, c, h.state.pocketPersonaActorId)).map((c) => [c.id, c.title])]);
}
var refresh = (h, action, data = {}) => h.action(h.app, action, data);
function webData(h) {
  return h.ui.private && h.app === "browser" ? h.ui.privateBrowser || { pages: [], places: [], tabs: [], activeTab: "", history: [], bookmarks: [], quizzes: [] } : nativeFor(h.state).browser;
}
function webAction(h, action, data = {}) {
  refresh(h, action, { ...data, private: h.app === "browser" && h.ui.private });
}
function shareWeb(h, root, id) {
  const recipient = conversations(h, "web-recipient");
  root.append(recipient, act5("Share in conversation", () => webAction(h, "share", { id, conversationId: h.ui.drafts["web-recipient"] })));
}
function quiz(h, root, value) {
  const result = quizResult(value), intro = card(value.title, value.summary);
  root.append(intro);
  const form = el("form", "lp-native-form"), answers = h.ui.quizAnswers[value.id] || (h.ui.quizAnswers[value.id] = value.answers ? [...value.answers] : []);
  value.questions.forEach((q, i) => {
    const group = el("fieldset", "lp-quiz-question");
    group.append(el("legend", "", `${i + 1}. ${q.text}`));
    q.choices.forEach((choice, j) => {
      const row = el("label", "lp-native-choice"), control = el("input");
      control.type = "radio";
      control.name = `quiz-${value.id}-${i}`;
      control.value = String(j);
      control.checked = answers[i] === j;
      control.onchange = () => {
        answers[i] = j;
      };
      row.append(control, el("span", "", choice.text));
      group.append(row);
    });
    form.append(group);
  });
  const finish = button("See my result", "lp-button lp-button-primary");
  finish.type = "submit";
  finish.disabled = h.busy;
  form.append(finish);
  form.onsubmit = (e) => {
    e.preventDefault();
    webAction(h, "quiz_answer", { id: value.id, answers: [...answers] });
  };
  root.append(form);
  if (result) {
    const resultCard = card(result.title, result.text);
    resultCard.classList.add("lp-quiz-result");
    shareWeb(h, resultCard, value.id);
    root.append(resultCard);
  }
  const contacts = select4(h, "quiz-contact", "Try it with a contact", [["", "Choose a contact"], ...h.state.contacts.filter((c) => !hiddenDatingContact(h.state, c.id)).map((c) => [c.id, c.name])]);
  root.append(contacts, act5("Ask them to take the quiz", () => webAction(h, "quiz_partner", { id: value.id, contactId: h.ui.drafts["quiz-contact"] })));
  if (value.partner) {
    const partnerResult = quizResult(value, value.partner.answers);
    root.append(card(`${value.partner.name} · ${partnerResult?.title || "Result"}`, partnerResult?.text || ""));
  }
}

