    identityBrief: draft.identityBrief,
    description: draft.identityBrief,
    phoneProfile: draft.phoneProfile,
    accent: draft.accent,
    colorMode: "pocket",
    messagingStyle: draft.messagingStyle,
    avatarOverrideUrl: draft.avatarUrl || "",
