  quickRefresh.title = "Refresh feed";
  quickRefresh.hidden = Boolean(ui.dmOpen || ui.serverOpen || ui.peopleOpen || ui.settingsOpen);
  refresh.setAttribute("aria-label", "Refresh feed now");
