    target.append(new Option("Choose a conversation", ""));
    for (const c of conversations)
      target.append(new Option(`${c.channel === "dating" ? "Lumistry · " : ""}${c.title}`, c.id));
    if (!conversations.some((c) => c.id === this.spotifyTarget))
      this.spotifyTarget = conversations[0]?.id || "";
    target.value = this.spotifyTarget;
    const key = JSON.stringify([this.activeContext(), this.spotifyTarget]);
    if (this.spotifyTarget && this.spotifyPlayerState?.key !== key)
      this.loadSpotifyPlayer(this.spotifyTarget);
    const player = this.spotifyPlayerState?.key === key ? this.spotifyPlayerState : null;
    target.onchange = () => {
      this.spotifyTarget = target.value;
      this.spotifyPlayerState = null;
      this.render(false);
    };
