    amount.max = "525600";
    amount.step = "1";
    amount.value = "1";
    amount.required = true;
    const unit = el("select", "lp-select");
    for (const [value, label] of [["1", "Minutes"], ["60", "Hours"], ["1440", "Days"]])
      unit.append(new Option(label, value));
